    { id: 'q76', p: ['xe1'], type: 'num', lvl: 3, tag: '🖼 Diagram', img: '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 200 200" width="200" height="200" stroke-linecap="round" role="img"><line x1="40" y1="10" x2="160" y2="10" stroke="currentColor" stroke-width="1.4"/><line x1="40" y1="10" x2="46" y2="16" stroke="currentColor" stroke-width="1"/><line x1="48" y1="10" x2="54" y2="16" stroke="currentColor" stroke-width="1"/><line x1="56" y1="10" x2="62" y2="16" stroke="currentColor" stroke-width="1"/><line x1="64" y1="10" x2="70" y2="16" stroke="currentColor" stroke-width="1"/><line x1="72" y1="10" x2="78" y2="16" stroke="currentColor" stroke-width="1"/><line x1="80" y1="10" x2="86" y2="16" stroke="currentColor" stroke-width="1"/><line x1="88" y1="10" x2="94" y2="16" stroke="currentColor" stroke-width="1"/><line x1="96" y1="10" x2="102" y2="16" stroke="currentColor" stroke-width="1"/><line x1="104" y1="10" x2="110" y2="16" stroke="currentColor" stroke-width="1"/><line x1="112" y1="10" x2="118" y2="16" stroke="currentColor" stroke-width="1"/><line x1="120" y1="10" x2="126" y2="16" stroke="currentColor" stroke-width="1"/><line x1="128" y1="10" x2="134" y2="16" stroke="currentColor" stroke-width="1"/><line x1="136" y1="10" x2="142" y2="16" stroke="currentColor" stroke-width="1"/><line x1="144" y1="10" x2="150" y2="16" stroke="currentColor" stroke-width="1"/><line x1="152" y1="10" x2="158" y2="16" stroke="currentColor" stroke-width="1"/><line x1="100" y1="10" x2="100" y2="80" stroke="currentColor" stroke-width="1.4"/><rect x="88" y="80" width="24" height="14" fill="#D9A520" stroke="currentColor" stroke-width="1.4" fill-opacity="0.5"/><text x="116" y="92" text-anchor="start" font-family="Inter,Arial,sans-serif" font-size="11" fill="currentColor">4.0 kg</text><line x1="100" y1="94" x2="100" y2="150" stroke="currentColor" stroke-width="1.4"/><rect x="84" y="150" width="32" height="18" fill="#D9A520" stroke="currentColor" stroke-width="1.4" fill-opacity="0.5"/><text x="120" y="164" text-anchor="start" font-family="Inter,Arial,sans-serif" font-size="11" fill="currentColor">6.0 kg</text><text x="106" y="45" text-anchor="start" font-family="Inter,Arial,sans-serif" font-size="11" fill="currentColor">steel, 1.5 m</text><text x="106" y="124" text-anchor="start" font-family="Inter,Arial,sans-serif" font-size="11" fill="currentColor">brass, 1.0 m</text></svg>', q: 'Steel wire 1.5 m with 4.0 kg and brass wire 1.0 m with 6.0 kg hang as shown; diameter 0.25 cm (Y_steel = 2.0 × 10¹¹ N m⁻², g = 9.8). Elongation of steel is about:', o: ['0.9 × 10⁻⁴ m', '1.3 × 10⁻⁴ m', '2.98 × 10⁻⁴ m', '1.49 × 10⁻⁴ m'], a: 3, e: 'Steel carries 10 kg.', sol: ['F_steel = (4 + 6) × 9.8 = 98 N', 'A = π(1.25 × 10⁻³)² = 4.91 × 10⁻⁶ m²', 'ΔL = FL/(AY) = 98 × 1.5/(4.91 × 10⁻⁶ × 2 × 10¹¹)', 'Answer: ≈ 1.49 × 10⁻⁴ m'] },
    { id: 'q77', p: ['xe1'], type: 'num', lvl: 3, q: 'An aluminium cube of edge 10 cm has one face fixed to a wall and 100 kg hung from the opposite face (G = 25 GPa, g = 9.8). Vertical deflection is:', o: ['3.92 × 10⁻⁷ m', '3.92 × 10⁻⁵ m', '3.92 × 10⁻⁹ m', '9.8 × 10⁻⁷ m'], a: 0, e: 'Δx = FL/(AG).', sol: ['F = 980 N, A = 0.01 m², L = 0.1 m', 'Δx = FL/(AG)', '= 980 × 0.1/(0.01 × 25 × 10⁹)', 'Answer: 3.92 × 10⁻⁷ m'] },
    { id: 'q78', p: ['xe2'], type: 'num', lvl: 2, q: 'A steel cable of radius 1.5 cm should not exceed a stress of 10⁸ N m⁻². The maximum load it can support is:', o: ['7.07 × 10² N', '7.07 × 10⁴ N', '1.5 × 10⁶ N', '7.07 × 10⁶ N'], a: 1, e: 'F = stress × A.', sol: ['A = π(1.5 × 10⁻²)² = 7.07 × 10⁻⁴ m²', 'F = 10⁸ × A', '= 7.07 × 10⁴', 'Answer: 7.07 × 10⁴ N'] },
    { id: 'q79', p: ['xe2'], type: 'num', lvl: 3, q: '100.0 L of water under a pressure increase of 100.0 atm (1 atm = 1.013 × 10⁵ Pa) changes volume by 0.5 L. Bulk modulus of water is about:', o: ['2.0 × 10⁷ Pa', '5 × 10⁻³ Pa', '2.0 × 10⁹ Pa', '1.0 × 10⁵ Pa'], a: 2, e: 'B = p/(ΔV/V).', sol: ['p = 100 × 1.013 × 10⁵ = 1.013 × 10⁷ Pa', 'ΔV/V = 0.5/100 = 5 × 10⁻³', 'B = 1.013 × 10⁷/5 × 10⁻³', 'Answer: ≈ 2.0 × 10⁹ Pa'] },
    { id: 'q80', p: ['xe2'], type: 'num', lvl: 2, q: 'How much should the pressure on a litre of water (B = 2.2 × 10⁹ Pa) be changed to compress it by 0.10%?', o: ['2.2 × 10⁹ Pa', '2.2 × 10³ Pa', '2.2 × 10⁷ Pa', '2.2 × 10⁶ Pa'], a: 3, e: 'Δp = B ΔV/V.', sol: ['ΔV/V = 0.001', 'Δp = B × ΔV/V', '= 2.2 × 10⁹ × 10⁻³', 'Answer: 2.2 × 10⁶ Pa'] },
    { id: 'q81', p: ['xe2'], type: 'num', lvl: 3, q: 'A copper cube of edge 10 cm (B = 140 × 10⁹ Pa) is subjected to a hydraulic pressure of 7.0 × 10⁶ Pa. Its volume contraction is:', o: ['5 × 10⁻² cm³', '5 × 10⁻⁴ cm³', '0.5 cm³', '5 cm³'], a: 0, e: 'ΔV = pV/B.', sol: ['V = 10³ cm³ = 10⁻³ m³', 'ΔV = pV/B = 7 × 10⁶ × 10⁻³/1.4 × 10¹¹', '= 5 × 10⁻⁸ m³', 'Answer: 5 × 10⁻² cm³'] },
    { id: 'q82', p: ['in1'], type: 'mcq', lvl: 1, q: 'A rigid body generally means:', o: ['A hard solid object having a definite shape and size', 'A body that flows', 'A body with no mass', 'A gas in a container'], a: 0, e: '8.1.' },
    { id: 'q83', p: ['ym1'], type: 'st', lvl: 2, st: ['The modulus of elasticity is the ratio of strain to stress.', 'The proportional region OA is of great importance for structural and manufacturing designs.'], a: 3, e: 'It is stress/strain.' },
    { id: 'q84', p: ['e84'], type: 'st', lvl: 2, st: ['In Example 8.4, the force is applied parallel to the narrow face of the slab.', 'The area used to find shearing stress is 50 cm × 50 cm.'], a: 2, e: 'It is 50 cm × 10 cm = 0.05 m².' },
    { id: 'q85', p: ['e85', 'bm1'], type: 'st', lvl: 2, st: ['Water is completely incompressible at such depths.', 'The pressure at the bottom of a 3000 m deep ocean is about 3 × 10⁷ N m⁻².'], a: 3, e: 'It compresses by 1.36%.' },
    { id: 'q86', p: ['ap1'], type: 'st', lvl: 1, st: ['Designing columns, beams and supports needs knowledge of strength of materials.', 'Beams used in bridges commonly have an I-shaped cross-section.'], a: 0, e: '8.6.' }
